  const entries = Array.isArray(prefer) ? prefer : prefer ? [prefer] : [];
  return entries
    .map((p) => (typeof p === 'string' ? p : p?.executor))
    .map((id) => runnerConfig.executors?.[id])
    .filter(Boolean)
    .map((executor) => deriveProviderFamily(executor));
}

